    """1. Dotation actuelle de chaque tournée = point de départ de l'historique.
    2. Type de demande « Modification de dotation » avec une étape de validation
       « Direction générale » (rôle dg s'il existe ; modifiable dans
       Paramètres › Circuits de validation)."""
    Tournee = apps.get_model('parametrage', 'Tournee')
    ChangementDotation = apps.get_model('parametrage', 'ChangementDotation')
    TypeDemande = apps.get_model('demandes', 'TypeDemande')
    NiveauValidation = apps.get_model('demandes', 'NiveauValidation')
    Role = apps.get_model('accounts', 'Role')

    for t in Tournee.objects.all():
        ChangementDotation.objects.get_or_create(
            tournee=t, statut='initiale',
            defaults={'nouvelle_dotation': t.dotation, 'motif': 'Reprise de la dotation existante'},
        )

    type_dotation, cree = TypeDemande.objects.get_or_create(code='dotation', defaults={
        'nom': 'Modification de dotation (tournée)',
        'description': 'Créée depuis Paramètres › Tournées. La tournée est mise à jour à l\'approbation finale.',
        'nb_niveaux': 1, 'actif': True,
    })
    if cree:
        NiveauValidation.objects.create(
            type_demande=type_dotation, niveau=1, libelle='Direction générale',
            role_min=Role.objects.filter(code='dg').first(),
        )


